parameters.jsCode:
const rows = $input.all().map((item) => item.json);
const notifications = [];

for (const row of rows) {
  const employeeName = `${row.first_name} ${row.last_name}`;
  const days = Number(row.days_remaining);

  let notificationType = null;
  if (days === 30) notificationType = 'manager_prepare_evaluation';
  if (days === 14) notificationType = 'reminder';
  if (days === 7) notificationType = 'escalation';
  if (days === 0) notificationType = 'end_date_resolution';

  if (!notificationType) continue;

  notifications.push({
    employee_id: row.id,
    employee_name: employeeName,
    position: row.position,
    probation_end_date: row.probation_end_date,
    days_remaining: days,
    notification_type: notificationType,
    manager_email: row.manager_email || null,
    employee_email: row.employee_email || null
  });
}

return notifications.map((record) => ({ json: record }));

